import{_ as p,a0 as a,w as o,s as r,ao as u,I as i,a1 as n,A as l,x as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const B=JSON.parse('{"title":"如何在Ubuntu上使用MultiSystem創建多啓動USB盤 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Ubuntu上使用MultiSystem創建多啓動USB盤 | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Ubuntu上使用MultiSystem創建多啓動USB盤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Ubuntu上使用MultiSystem創建多啓動USB盤 | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20141127 How To Create A Multiboot USB From Ubuntu Using MultiSystem","title":"如何在Ubuntu上使用MultiSystem創建多啓動USB盤","tag":"201501","desc":""},"relativePath":"201501/20141127 How To Create A Multiboot USB From Ubuntu Using MultiSystem.md","filePath":"[post].md"}'),m={name:"201501/20141127 How To Create A Multiboot USB From Ubuntu Using MultiSystem.md"};function d(S,t,b,y,g,M){const s=a("Link");return o(),r("div",null,[t[15]||(t[15]=u('<h1 id="如何在ubuntu上使用multisystem創建多啓動usb盤" tabindex="-1">如何在Ubuntu上使用MultiSystem創建多啓動USB盤 <a class="header-anchor" href="#如何在ubuntu上使用multisystem創建多啓動usb盤" aria-label="Permalink to “如何在Ubuntu上使用MultiSystem創建多啓動USB盤”">​</a></h1><h3 id="介紹" tabindex="-1">介紹 <a class="header-anchor" href="#介紹" aria-label="Permalink to “介紹”">​</a></h3><p>也許還有不少人不知道<strong>MultiSystem</strong>，它是一個用來在Linux系統中創建多啓動usb盤的小型的開源軟件。使用這個工具，我們可以在USB中創建任意多的可啓動Linux發行版。你所需要的只是網絡鏈接（只在MultiSystem安裝的時候需要），以及一個足夠大的USB盤，這取決於你想在USB盤中放入發行版的數量。</p><h3 id="在-ubuntu-14-10-14-04-安裝multisystem" tabindex="-1">在 Ubuntu 14.10/14.04 安裝MultiSystem <a class="header-anchor" href="#在-ubuntu-14-10-14-04-安裝multisystem" aria-label="Permalink to “在 Ubuntu 14.10/14.04 安裝MultiSystem”">​</a></h3><h4 id="手動安裝" tabindex="-1">手動安裝: <a class="header-anchor" href="#手動安裝" aria-label="Permalink to “手動安裝:”">​</a></h4>',5)),i("p",null,[n(s,{href:"http://liveusb.info/multisystem/install-depot-multisystem.sh.tar.bz2"},{default:l(()=>[...t[0]||(t[0]=[e("下載 MultiSystem",-1)])]),_:1}),t[1]||(t[1]=e("腳本，並解壓到任意地方。進入解壓的地址，使用下面的命令運行腳本。",-1))]),t[16]||(t[16]=u(`<pre><code>sudo ./install-depot-multisystem.sh
</code></pre><h4 id="使用-ppa-安裝" tabindex="-1">使用 PPA 安裝: <a class="header-anchor" href="#使用-ppa-安裝" aria-label="Permalink to “使用 PPA 安裝:”">​</a></h4><p>當然，你也可以用下面的命令來更簡單地使用PPA來安裝MultiSystem。</p><pre><code>sudo apt-add-repository &#39;deb http://liveusb.info/multisystem/depot all main&#39;
wget -q -O - http://liveusb.info/multisystem/depot/multisystem.asc | sudo apt-key add -
sudo apt-get update
sudo apt-get install multisystem
</code></pre><p>安裝完之後，它會自動打開MultiSystem。只要點擊關閉按鈕退出。</p><h3 id="安裝之後" tabindex="-1">安裝之後 <a class="header-anchor" href="#安裝之後" aria-label="Permalink to “安裝之後”">​</a></h3><p>MultiSystem 安裝完成後，可以插入你的USB，並通過Unity Dash或者菜單運行MultiSystem。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/Menu_0012.png" alt=""></p><p>第一次啓動時，MultiSystem界面看起來會像下面這樣。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/MultiSystem_002.png" alt=""></p><p>選擇USB設備，點擊<strong>確認</strong>按鈕。如果你看到下面的錯誤窗口，不必擔心，它説的是USB設備沒有標籤。點擊OK讓MultiSystem自動設置標籤。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/Error_003.png" alt=""></p><p>那麼，拔出/重新插入USB，再次運行MultiSystem。選擇USB盤，再次點擊確認。現在，你被要求確認在USB中安裝Grub2.點擊OK繼續。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/gtkdialog_004.png" alt=""></p><p>最終，你會高興地看到MultiSystem的界面。現在，時候創建多啓動USB盤。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/MultiSystem_005.png" alt=""></p><h3 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to “使用”">​</a></h3><p>MultiSystem非常容易使用。將ISO文件拖入MultiSystem窗口中。如果不行的話，點擊底部的<strong>cd 按鈕</strong>來選擇ISO文件。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/MultiSystem_006.png" alt=""></p><p>現在，MultiSystem會從ISO中拷貝文件，並讓USB可啓動。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/MultiSystem_007.png" alt=""></p><p>相似地，你可以在你的USB中加入任意多的發行版。我這次加入了兩個Linux發行版：CentOS 6.5和Android。</p><p>加完ISO文件後，你會在MultiSystem的主窗口中看到可啓動的發行版列表了。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/MultiSystem_008.png" alt=""></p><p>就是這樣。我們的多啓動USB盤就可以使用了。重啓系統，並在BIOS中設置USB優先啓動。選擇你想要安裝的發行版並開始安裝系統。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/QEMU_009.png" alt=""></p><p>此外，MultiSystem含有一些其它的選項：</p><ul><li>Grub 設置</li><li>Grub 和 Burg 的bootloader更新</li><li>下載 LiveCD</li><li>VirtualBox 安裝</li><li>格式化USB盤</li><li>還有更多選項</li></ul><p>這些額外選項可以在MultiSystem的<strong>菜單</strong>標籤裏面看到。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/MultiSystem_010.png" alt=""></p><p>同樣，你也可以在Ubuntu中使用QEMU或者Oracle VirtualBox測試多啓動USB盤。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/MultiSystem_011.png" alt=""></p><p>MultiSystem工具是我測試到現在最棒和最有用的一款工具。這款工具對那些想要在他們的機器上安裝多個系統的人是非常有用的。在你外出的時候，你不必再攜帶CD/DVD袋了。只要買一個16GB或者32GB的USB就行，並下載所有你想要的系統，隨心所欲的安裝系統即可。</p><p>並且，一個對於Windows系統用户的好消息是它也支持Windows系統。我在Windows 7上測試過，它可以工作！</p><p>享受吧！</p><hr>`,36)),i("p",null,[t[3]||(t[3]=e("via: ",-1)),n(s,{href:"http://www.unixmen.com/create-multiboot-usb-ubuntu-using-multisystem/"},{default:l(()=>[...t[2]||(t[2]=[e("http://www.unixmen.com/create-multiboot-usb-ubuntu-using-multisystem/",-1)])]),_:1})]),i("p",null,[t[7]||(t[7]=e("作者：",-1)),n(s,{href:"http://www.unixmen.com/author/sk/"},{default:l(()=>[...t[4]||(t[4]=[e("SK",-1)])]),_:1}),t[8]||(t[8]=e(" 譯者：",-1)),n(s,{href:"https://github.com/geekpi"},{default:l(()=>[...t[5]||(t[5]=[e("geekpi",-1)])]),_:1}),t[9]||(t[9]=e(" 校對：",-1)),n(s,{href:"https://github.com/wxy"},{default:l(()=>[...t[6]||(t[6]=[e("wxy",-1)])]),_:1})]),i("p",null,[t[12]||(t[12]=e("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原創翻譯，",-1)),n(s,{href:"http://linux.cn/"},{default:l(()=>[...t[11]||(t[11]=[e("Linux中國",-1)])]),_:1}),t[14]||(t[14]=e(" 榮譽推出",-1))])])}const f=p(m,[["render",d]]);export{B as __pageData,f as default};
